60	/**
61	 * AIDispatcher - Autonomous capability selection and execution.
62	 * Refactored to use unified ModelClient substrate.
63	 */
64	export class AIDispatcher {
65	    private readonly serviceStates: Map<AIServiceType, ServiceState> = new Map();
66	
67	    constructor(
68	        private readonly client: ModelClient,
69	        private readonly workforce: WorkforceManifest
70	    ) {
71	        // Initialize service states
72	        const types: AIServiceType[] = ['GEMINI', 'CLOUDFLARE', 'OLLAMA', 'HUGGINGFACE'];
73	        types.forEach(t => this.serviceStates.set(t, 'IDLE'));
74	    }
75	
76	    async dispatch(request: { capabilityId: string; payload: string; context?: any; snapshot?: RoutingSnapshot; modelOverride?: string }): Promise<Result<any>> {
77	        const capability = CapabilityRegistry[request.capabilityId];
78	        if (!capability) {
79	            return { ok: false, error: new Error(`Capability ${request.capabilityId} not registered.`) };
80	        }
81	
82	        const taskClass = capability.taskClass || this.classifyTask(request.capabilityId, request.payload);
83	        const policy = MODEL_POLICY[taskClass] || MODEL_POLICY.AGENTIC_REASONING;
84	        
85	        // Use provided snapshot or get current from CNS
86	        const snapshot = request.snapshot || CNSGodheadPulseVolley.getInstance()?.getRoutingSnapshot();
87	
88	        const modelId = request.modelOverride || this.resolveModelFromPolicy(policy, capability, snapshot);
89	        
90	        const start = Date.now();
91	        try {
92	            this.serviceStates.set(capability.serviceType, 'READY');
93	            const result = await this.client.execute({
94	                model: modelId,
95	                prompt: request.payload,
96	                systemPrompt: `Capability: ${capability.name}\nTask: ${taskClass}\nDomain: ${capability.domain || 'GENERAL'}`
97	            });
98	
99	            const latency = Date.now() - start;
100	            
101	            // Causal Routing Audit
102	            this.auditDecision({
103	                tick: snapshot?.tick || -1,
104	                taskClass,
105	                policy,
106	                snapshotHash: snapshot ? this.hashSnapshot(snapshot) : 'LIVE',
107	                selectedModel: modelId,
108	                selectedTier: this.getTierFromModel(modelId, capability),
109	                latencyMs: latency,
110	                success: result.ok
111	            });
112	
113	            return result;
114	        } catch (error) {
115	            this.serviceStates.set(capability.serviceType, 'ERROR');
116	            const errorMessage = error instanceof Error ? error.message : String(error);
117	
118	            if (capability.fallback) {
119	                logger.warn({ capabilityId: request.capabilityId, fallback: capability.fallback, error: errorMessage }, 'Dispatch exception, attempting fallback');
120	                return this.dispatch({ ...request, capabilityId: capability.fallback });
121	            }
122	
123	            return {
124	                ok: false,
125	                error: new Error(errorMessage)
126	            };
127	        }
128	    }
129	
130	    private classifyTask(id: string, payload: string): TaskClass {
131	        if (id.includes('vision') || id.includes('eye') || payload.includes('.png')) return "VISION";
132	        if (id.includes('search') || id.includes('retrieve') || id.includes('atlas')) return "RETRIEVAL";
133	        if (id.includes('completion') || id.includes('scaffold')) return "COMPLETION";
134	        if (id.includes('generate') || id.includes('creative')) return "CREATIVE_EXPANSION";
135	        return "AGENTIC_REASONING";
136	    }
137	
138	    private resolveModelFromPolicy(policy: RoutingPolicy, capability: AICapability, snapshot?: RoutingSnapshot): string {
139	        const rolodex = this.client.getRolodex();
140	        
141	        // 0. Policy-Driven Cloud Gate
142	        let cloudStatus = 'ONLINE';
143	        let cloudEffect = 'NONE';
144	
145	        if (snapshot) {
146	            cloudStatus = snapshot.cloudHealth.status;
147	            cloudEffect = snapshot.cloudHealth.effect;
148	        } else {
149	            const signal = SubstrateResolver.getCloudSignal();
150	            cloudStatus = signal.status;
151	            cloudEffect = signal.effect;
152	        }
153	
154	        const forceLocal = !policy.allowCloud || cloudEffect === 'BLOCK_CLOUD_TASKS';
155	
156	        // 1. Try Primary Tier (if not forced local or primary is already local)
157	        if (!forceLocal || policy.primary !== 'CLOUD') {
158	            const primaryModel = this.getModelForTier(policy.primary, capability);
159	            const isHealthy = snapshot ? snapshot.modelHealthMap[primaryModel] : rolodex?.isModelHealthy(primaryModel);
160	            if (isHealthy) return primaryModel;
161	        }
162	
163	        // 2. Try Fallback Tiers in order
164	        for (const tier of policy.fallback) {
165	            if (forceLocal && tier === 'CLOUD') continue;
166	            const fallbackModel = this.getModelForTier(tier, capability);
167	            const isHealthy = snapshot ? snapshot.modelHealthMap[fallbackModel] : rolodex?.isModelHealthy(fallbackModel);
168	            if (isHealthy) return fallbackModel;
169	        }
170	
171	        // 3. Absolute Floor: Sovereign Local
172	        return this.getModelForTier("SOVEREIGN_LOCAL", capability);
173	    }
174	
175	    private getModelForTier(tier: ModelTier, capability: AICapability): string {
176	        switch (tier) {
177	            case "SOVEREIGN_LOCAL": 
178	                return this.client.config.masterLocalModel || 'deepseek-r1:8b';
179	            case "ENRICHED_LOCAL": 
180	                return this.client.config.localFallbackModel || 'deepseek-r1:8b';
181	            case "CLOUD": 
182	                return capability.modelId || this.client.config.orchestratorModel;
183	        }
184	    }
185	
186	    private getTierFromModel(modelId: string, capability: AICapability): ModelTier {
187	        if (modelId === (this.client.config.masterLocalModel || 'deepseek-r1:8b')) return "SOVEREIGN_LOCAL";
188	        if (modelId === capability.modelId) return "CLOUD";
189	        return "ENRICHED_LOCAL";
190	    }
191	
192	    private hashSnapshot(snapshot: RoutingSnapshot): string {
193	        // Simple hash of the snapshot state
194	        const data = `${snapshot.tick}-${snapshot.cloudHealth.status}-${snapshot.substrateHealth}`;
195	        return `snap:${snapshot.tick}`;
196	    }
197	
198	    private auditDecision(audit: RoutingDecisionAudit): void {
199	        logger.info({ 
200	            tick: audit.tick, 
201	            task: audit.taskClass, 
202	            model: audit.selectedModel, 
203	            snap: audit.snapshotHash,
204	            tier: audit.selectedTier
205	        }, '🧬 Cognitive Routing Audit');
206	    }
207	
208	    public getServiceState(type: AIServiceType): ServiceState {
209	        return this.serviceStates.get(type) || 'IDLE';
210	    }
211	
212	    public healthCheck(): { online: boolean; details: string } {
213	        const statuses = Array.from(this.serviceStates.entries())
214	            .map(([type, state]) => `${type}: ${state}`)
215	            .join(', ');
216	        return {
217	            online: true,
218	            details: `AI Dispatcher ready. Service States: ${statuses}`
219	        };
220	    }
221	}
