369	    private async callGemini(params: ModelCallParams, startTime: number): Promise<Result<ModelResponse>> {
370	        const apiKey = this.config.secondaryCloudApiKey;
371	        if (!apiKey) {
372	            return { ok: false, error: new Error('SECONDARY_CLOUD_API_KEY not set Ã¢â‚¬â€ cannot call cloud substrate') };
373	        }
374	
375	        // Tiered Gemini Fallback Sequence
376	        const primaryModelId = params.model.replace('gemini:', '');
377	        const fallbackSequence = [
378	            primaryModelId,
379	            this.config.geminiFlashModel,
380	            'gemini-1.5-flash-001',
381	            this.config.geminiProModel
382	        ];
383	
384	        // Deduplicate
385	        const uniqueSequence = Array.from(new Set(fallbackSequence));
386	        let lastError: Error | undefined;
387	
388	        for (const modelId of uniqueSequence) {
389	            const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelId}:generateContent?key=${apiKey}`;
390	
391	            const messages: Array<{ role: string; parts: Array<{ text: string }> }> = [];
392	
393	            if (params.systemPrompt) {
394	                messages.push({ role: 'user', parts: [{ text: params.systemPrompt }] });
395	                messages.push({ role: 'model', parts: [{ text: 'Understood.' }] });
396	            }
397	
398	            messages.push({ role: 'user', parts: [{ text: params.prompt }] });
399	
400	            const body = {
401	                contents: messages,
402	                generationConfig: {
403	                    temperature: params.temperature ?? 0.3,
404	                    maxOutputTokens: params.maxTokens ?? 8192
405	                }
406	            };
407	
408	            try {
409	                let response = await undiciFetch(url, {
410	                    method: 'POST',
411	                    headers: { 'Content-Type': 'application/json' },
412	                    body: JSON.stringify(body),
413	                    signal: AbortSignal.timeout(this.getTimeoutByYaoState(params.yaoState))
414	                });
415	
416	                if (!response.ok) {
417	                    const errorText = await response.text();
418	
419	                    // If 404, try next model in sequence
420	                    if (response.status === 404) {
421	                        logger.warn({ modelId, status: 404 }, 'Gemini model not found (404), trying next in sequence...');
422	                        lastError = new Error(`Gemini model ${modelId} not found: ${errorText}`);
423	                        continue;
424	                    }
425	
426	                    logger.warn({ status: response.status, errorText }, 'Secondary Cloud API failed. Attempting substrate-specific CLI fallback...');
427	
428	                    try {
429	                        const { stdout } = await execAsync('gcloud auth print-access-token');
430	                        const token = stdout.trim();
431	                        if (token) {
432	                            const fallbackUrl = `https://generativelanguage.googleapis.com/v1beta/models/${modelId}:generateContent`;
433	                            response = await undiciFetch(fallbackUrl, {
434	                                method: 'POST',
435	                                headers: {
436	                                    'Content-Type': 'application/json',
437	                                    'Authorization': `Bearer ${token}`
438	                                },
439	                                body: JSON.stringify(body),
440	                                signal: AbortSignal.timeout(this.getTimeoutByYaoState(params.yaoState))
441	                            });
442	
443	                            if (!response.ok) {
444	                                const fallbackErrorText = await response.text();
445	                                lastError = new Error(`Gemini API & GCloud fallback failed: ${fallbackErrorText}`);
446	                                continue;
447	                            }
448	                        } else {
449	                            lastError = new Error(`Gemini API ${response.status}: ${errorText}`);
450	                            continue;
451	                        }
452	                    } catch (fallbackErr) {
453	                        logger.error({ err: fallbackErr }, 'GCloud CLI not available or auth failed');
454	                        lastError = new Error(`Gemini API ${response.status}: ${errorText}`);
455	                        continue;
456	                    }
457	                }
458	
459	                const data = await response.json() as {
460	                    candidates?: Array<{
461	                        content?: { parts?: Array<{ text?: string }> };
462	                        finishReason?: string;
463	                    }>;
464	                    usageMetadata?: { totalTokenCount?: number };
465	                };
466	
467	                const text = data.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
468	                const latency = Date.now() - startTime;
469	
470	                logger.debug({ model: `gemini:${modelId}`, latency, tokens: data.usageMetadata?.totalTokenCount }, 'Secondary Cloud call complete');
471	
472	                return {
473	                    ok: true,
474	                    value: {
475	                        response: text,
476	                        model: `gemini:${modelId}`,
477	                        latency,
478	                        tokensUsed: data.usageMetadata?.totalTokenCount
479	                    }
480	                };
481	            } catch (err) {
482	                logger.error({ err, modelId }, 'Secondary Cloud network error for specific Gemini model');
483	                lastError = err as Error;
484	            }
485	        }
486	
487	        return { ok: false, error: lastError || new Error('All Gemini retry attempts failed.') };
488	    }
