490	    private async callOllama(params: ModelCallParams, startTime: number): Promise<Result<ModelResponse>> {
491	        const url = `${this.config.ollamaBaseUrl}/api/generate`;
492	
493	        const fullPrompt = params.systemPrompt
494	            ? `${params.systemPrompt}\n\n${params.prompt}`
495	            : params.prompt;
496	
497	        const body = {
498	            model: params.model,
499	            prompt: fullPrompt,
500	            stream: false,
501	            images: params.images, // Multimodal support
502	            format: params.format === 'text' ? undefined : (params.format === 'json' ? 'json' : (this.config.outputFormat === 'json' ? 'json' : undefined)),
503	            options: {
504	                temperature: params.temperature ?? this.config.temperature,
505	                top_p: this.config.topP,
506	                repeat_penalty: this.config.repeatPenalty,
507	                num_ctx: this.config.numCtx,
508	                stop: this.config.stopSequences,
509	                num_predict: params.maxTokens ?? 4096
510	            }
511	        };
512	
513	        try {
514	            const controller = new AbortController();
515	            const signal = params.signal || AbortSignal.timeout(86_400_000); // 24 hours
516	            const combinedSignal = AbortSignal.any([signal, controller.signal]);
517	
518	            const response = await undiciFetch(url, {
519	                method: 'POST',
520	                headers: { 'Content-Type': 'application/json' },
521	                body: JSON.stringify(body),
522	                // Massive local timeout: natively handled by Undici dispatcher
523	                dispatcher: this.customAgent,
524	                signal: combinedSignal
525	            } as any);
526	
527	            // LOGGING LOOP: The Persistence Heartbeat
528	
529	            const persistenceInterval = setInterval(() => {
530	                const elapsed = Math.floor((Date.now() - startTime) / 1000);
531	                const minutes = Math.floor(elapsed / 60);
532	                const seconds = elapsed % 60;
533	                logger.info({
534	                    model: params.model,
535	                    elapsed: `${minutes}m ${seconds}s`,
536	                    pulse: 'STILL_REASONING'
537	                }, 'Î“Â¥Ã¿ Neural Pulse: Deep substrate calculation actively thinking...');
538	            }, 30000); // Pulse every 30s instead of 60s
539	
540	            try {
541	                if (!response.ok) {
542	                    clearInterval(persistenceInterval);
543	                    const errorText = await response.text();
544	                    logger.error({ status: response.status, model: params.model }, 'Ollama API error');
545	
546	                    // Activate cooldown on 429 rate limit responses
547	                    if (response.status === 429) {
548	                        logger.warn({ model: params.model }, 'Ollama 429 rate limit Ã¢â‚¬â€ activating HuggingFace fallback');
549	                        this.router?.activateOllamaCooldown();
550	                    }
551	
552	                    return { ok: false, error: new Error(`Ollama ${response.status}: ${errorText}`) };
553	                }
554	
555	                const data = await response.json() as { response?: string; done?: boolean };
556	                clearInterval(persistenceInterval);
557	                const latency = Date.now() - startTime;
558	
559	                logger.debug({ model: params.model, latency }, 'Ollama call complete');
560	
561	                return {
562	                    ok: true,
563	                    value: {
564	                        response: data.response ?? '',
565	                        model: params.model,
566	                        latency
567	                    }
568	                };
569	            } catch (err) {
570	                const error = err as Error;
571	                const errorMsg = error.message?.toLowerCase() ?? '';
572	                clearInterval(persistenceInterval);
573	
574	                // Check if this looks like a cooldown/ratelimit error
575	                if (errorMsg.includes('rate limit') ||
576	                    errorMsg.includes('cooldown') ||
577	                    errorMsg.includes('429') ||
578	                    errorMsg.includes('too many requests') ||
579	                    errorMsg.includes('resource exhausted') ||
580	                    errorMsg.includes('connect') ||
581	                    errorMsg.includes('econnrefused') ||
582	                    errorMsg.includes('timeout')) {
583	                    logger.warn({ model: params.model, error: errorMsg }, 'Ollama issue detected Ã¢â‚¬â€ activating Hugging Face fallback');
584	                    this.router?.activateOllamaCooldown();
585	                }
586	
587	                logger.error({ err: error, model: params.model }, 'Ollama network error');
588	                return { ok: false, error };
589	            }
590	        } catch (err) {
591	            logger.error({ err, model: params.model }, 'Critical error in Ollama call wrapper');
592	            return { ok: false, error: err as Error };
593	        }
594	    }
