484	     */
485	    public async startWithGracefulPort(orchestrator: any, startPort: number = 8788): Promise<{ port: number, url: string }> {
486	        let currentPort = startPort;
487	        const maxTries = 20;
488	
489	        for (let i = 0; i < maxTries; i++) {
490	            try {
491	                await this.startServer(currentPort, orchestrator);
492	                return { port: currentPort, url: `http://localhost:${currentPort}` };
493	            } catch (err: any) {
494	                if (err.code === 'EADDRINUSE') {
495	                    logger.warn({ port: currentPort }, 'Switchboard port in use, incrementing...');
496	                    currentPort++;
497	                    continue;
498	                }
499	                throw err;
500	            }
501	        }
502	        throw new Error(`Switchboard failed to bind to any port in range ${startPort}-${currentPort - 1}`);
503	    }
